-- Hosbah tenant queries.
-- name: InsertDomain :one
INSERT INTO domains (team_id, app_id, hostname, tls, verify_token) VALUES ($1, $2, $3, $4, $5) RETURNING *;

-- name: ListDomainsOfApp :many
SELECT * FROM domains WHERE app_id = $1 AND team_id = $2 ORDER BY hostname;

-- name: DomainOfApp :one
-- A domain of the app by id or by hostname.
SELECT * FROM domains
WHERE app_id = sqlc.arg('app_id')::text AND team_id = sqlc.arg('team_id')::text
  AND (id = sqlc.arg('ref')::text OR hostname = sqlc.arg('ref')::text);

-- name: DeleteDomainInTeam :execrows
DELETE FROM domains WHERE id = $1 AND team_id = $2;

-- name: MarkDomainVerified :exec
UPDATE domains SET verified_at = now(), updated_at = now() WHERE id = $1 AND team_id = $2;

-- name: TLSAllowed :one
-- System scope: Caddy's on-demand TLS ask. A certificate only for a verified auto-TLS domain.
SELECT ((SELECT count(*) FROM domains d WHERE d.hostname = $1 AND d.tls = 'auto' AND d.verified_at IS NOT NULL)
     + (SELECT count(*) FROM proxy_hosts p WHERE p.hostname = $1 AND p.tls = 'auto' AND p.enabled AND p.verified_at IS NOT NULL))::bigint AS n;

-- name: HostnameTaken :one
-- System scope: is this hostname routed anywhere in Hosbah (any team)?
SELECT ((SELECT count(*) FROM domains d WHERE d.hostname = $1) + (SELECT count(*) FROM proxy_hosts p WHERE p.hostname = $1))::bigint AS n;

-- name: SetDomainUpstream :exec
UPDATE domains SET upstream = sqlc.narg('upstream'), updated_at = now() WHERE id = sqlc.arg('id') AND team_id = sqlc.arg('team_id');
